+            }
+            jobStream = env.readTextFile(jobInput).flatMap(new JobEventParser());
+        }
+
+        WatermarkStrategy<TaskEvent> taskWatermarks = WatermarkStrategy
+                .<TaskEvent>forMonotonousTimestamps()
+                .withTimestampAssigner((event, timestamp) -> event.timestamp);
+
+        WatermarkStrategy<JobEvent> jobWatermarks = WatermarkStrategy
+                .<JobEvent>forMonotonousTimestamps()
+                .withTimestampAssigner((event, timestamp) -> event.timestamp);
+
+        DataStream<TaskEvent> submitTasks = taskStream
+                .assignTimestampsAndWatermarks(taskWatermarks)
+                .filter(event -> event.eventType == TaskEvent.EVENT_SUBMIT);
+
+        DataStream<JobEvent> finishedJobs = jobStream
+                .assignTimestampsAndWatermarks(jobWatermarks)
+                .filter(JobEvent::isTerminal);
+
+        KeyedStream<TaskEvent, Long> keyedTasks = submitTasks.keyBy(TaskEvent::getJobId);
+        KeyedStream<JobEvent, Long> keyedJobs = finishedJobs.keyBy(JobEvent::getJobId);
+
+        DataStream<Tuple2<Long, Long>> result = keyedTasks
+                .connect(keyedJobs)
+                .process(new LongestStageOnFinish(gapMicros));
+
+        if (outputPath != null) {
+            result.writeAsText(outputPath).setParallelism(1);
+        } else if (AppBase.out != null) {
+            result.addSink((SinkFunction<Tuple2<Long, Long>>) AppBase.out);
+        }
+
+        env.execute("LongestSessionPerJob");
+    }
