+    private static class LongestStageOnFinish extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Long>> {
+        private final long gapMicros;
+
+        private transient ValueState<Long> lastSubmitTime;
+        private transient ValueState<Long> currentCount;
+        private transient ValueState<Long> maxCount;
+        private transient ValueState<Long> finishTime;
+
+        LongestStageOnFinish(long gapMicros) {
+            this.gapMicros = gapMicros;
+        }
+
+        @Override
+        public void open(Configuration parameters) {
+            lastSubmitTime = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTime", Long.class));
+            currentCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentCount", Long.class));
+            maxCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxCount", Long.class));
+            finishTime = getRuntimeContext().getState(new ValueStateDescriptor<>("finishTime", Long.class));
