+            long curCount = valueOrZero(currentCount.value());
+            long max = valueOrZero(maxCount.value());
+
+            if (lastTime == null) {
+                curCount = 1L;
+            } else {
+                long delta = value.timestamp - lastTime;
+                if (delta > gapMicros) {
+                    if (curCount > max) {
+                        max = curCount;
+                    }
+                    curCount = 1L;
+                } else {
+                    curCount += 1L;
+                }
+            }
+
+            lastSubmitTime.update(value.timestamp);
+            currentCount.update(curCount);
+            maxCount.update(max);
+        }
+
+        @Override
+        public void processElement2(JobEvent value, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
+            if (!value.isTerminal()) {
+                return;
+            }
+            Long existingFinish = finishTime.value();
+            if (existingFinish != null) {
+                return;
+            }
+            finishTime.update(value.timestamp);
+            long timerTs = safeAdd(value.timestamp, gapMicros);
+            ctx.timerService().registerEventTimeTimer(timerTs);
+        }
+
+        @Override
+        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
+            long curCount = valueOrZero(currentCount.value());
+            long max = valueOrZero(maxCount.value());
+            if (curCount > max) {
+                max = curCount;
+            }
+            out.collect(Tuple2.of(ctx.getCurrentKey(), max));
+            clearState();
+        }
+
+        private long valueOrZero(Long value) {
+            return value == null ? 0L : value;
+        }
+
+        private long safeAdd(long base, long delta) {
+            if (delta > 0 && base > Long.MAX_VALUE - delta) {
+                return Long.MAX_VALUE;
+            }
+            if (delta < 0 && base < Long.MIN_VALUE - delta) {
+                return Long.MIN_VALUE;
+            }
+            return base + delta;
+        }
